with d as (
  insert into public.library_documents (title, school_level, subject, topic, keywords, summary, preview, verified_by_ai) values
  ('Startpaket STK120: Hypotesprövning steg för steg', 'university', 'Statistik STK120', 'Hypotesprövning', '{nollhypotes,p-värde,signifikansnivå,t-test}', 'Från nollhypotes till slutsats – med ett räknat exempel och vanliga fällor.', 'En hypotesprövning svarar på frågan: kan skillnaden bero på slumpen?', true),
  ('Startpaket STK120: Konfidensintervall utan krångel', 'university', 'Statistik STK120', 'Konfidensintervall', '{konfidensintervall,standardfel,t-fördelning}', 'Vad ett 95 %-intervall betyder och hur du räknar ut det.', 'Ett konfidensintervall är ett spann av rimliga värden för det sanna medelvärdet.', true),
  ('Startpaket Matte 1b: Linjära funktioner', 'gymnasium', 'Matte', 'Funktioner', '{y=kx+m,lutning,riktningskoefficient}', 'Lutning, skärning med y-axeln och hur du ritar en rät linje.', 'En linjär funktion skrivs y = kx + m. k är lutningen, m är var linjen skär y-axeln.', true),
  ('Startpaket Matte 1b: Ekvationer på 10 minuter', 'gymnasium', 'Matte', 'Algebra', '{ekvation,balansmetoden,x}', 'Balansmetoden: gör samma sak på båda sidor tills x står ensamt.', 'En ekvation är som en våg. Det du gör på ena sidan gör du på den andra.', true),
  ('Startpaket Historia: Första världskriget', 'gymnasium', 'SO', 'Historia', '{1914,allianser,skyttegravar,Versaillesfreden}', 'Orsaker, skyttegravskriget och freden som ledde vidare.', 'År 1914 drogs Europa in i ett krig som ingen trodde skulle bli så långt.', true),
  ('Startpaket Historia: Industriella revolutionen', 'hogstadiet', 'SO', 'Historia', '{ångmaskinen,fabriker,urbanisering}', 'Hur maskiner förändrade arbete, städer och vardag.', 'Kring 1750 började England bygga fabriker där maskiner gjorde jobbet.', true)
  returning id, title
)
insert into public.library_content (document_id, content)
select id, case
 when title like '%Hypotes%' then E'## Steg 1: Ställ upp hypoteserial\nNollhypotesen H0 säger att det inte finns någon skillnad. Mothypotesen H1 säger att det finns en.\n\n## Steg 2: Välj signifikansnivå\nOftast används 5 %. Det är risken du accepterar att förkasta en sann H0.\n\n## Steg 3: Räkna testvariabeln\nFör ett t-test: $t = \\frac{\\bar{x} - \\mu_0}{s/\\sqrt{n}}$. Exempel: medel 52, hypotes 50, s = 6, n = 36 ger t = 2.\n\n## Steg 4: Jämför och dra slutsats\np-värdet blir cirka 0,05. Är p mindre än 0,05 förkastar du H0. Skriv slutsatsen med vanliga ord.\n\n## Vanlig fälla\nAtt inte förkasta H0 betyder inte att H0 är bevisad. Det betyder bara att bevisen inte räcker.'
 when title like '%Konfidens%' then E'## Vad betyder det?\nEtt 95 %-intervall fångar det sanna medelvärdet i 95 av 100 upprepade stickprov.\n\n## Formeln\n$\\bar{x} \\pm t \\cdot \\frac{s}{\\sqrt{n}}$\n\n## Räknat exempel\nMedel 20, s = 4, n = 16. Standardfelet blir 4/4 = 1. Med t ≈ 2,13 blir intervallet 17,9 till 22,1.\n\n## Minnesknep\nStörre stickprov ger smalare intervall. Högre säkerhet ger bredare intervall.'
 when title like '%Linjära%' then E'## Grunden\nEn linjär funktion skrivs y = kx + m.\n\n## Lutningen k\nk visar hur mycket y ändras när x ökar med 1. Positivt k går uppåt, negativt k går nedåt.\n\n## Startvärdet m\nm är där linjen skär y-axeln, alltså y när x = 0.\n\n## Räkna ut k\n$k = \\frac{y_2 - y_1}{x_2 - x_1}$. Punkterna (1, 3) och (3, 7) ger k = 4/2 = 2.\n\n## Testa dig själv\nVad blir m för linjen genom (1, 3) med k = 2? Svar: 3 = 2 · 1 + m, så m = 1.'
 when title like '%Ekvationer%' then E'## Tänk på en våg\nDet du gör på ena sidan gör du alltid på den andra.\n\n## Exempel\n3x + 5 = 20. Ta bort 5 på båda sidor: 3x = 15. Dela med 3: x = 5.\n\n## Kontrollera\nSätt in x = 5: 3 · 5 + 5 = 20. Det stämmer!\n\n## Snabbknep\nTa först bort det som står ensamt, sedan det som multipliceras.'
 when title like '%Första%' then E'## Orsaker\nEuropa var delat i två allianser. Nationalism och kapprustning gjorde läget spänt.\n\n## Gnistan\nI juni 1914 sköts den österrikiske tronföljaren i Sarajevo. Allianserna drog in land efter land.\n\n## Skyttegravarna\nPå västfronten stod arméerna stilla i åratal. Miljontals soldater dog för några meter mark.\n\n## Slutet\nKriget slutade 1918. Versaillesfreden 1919 gav Tyskland hårda villkor, vilket skapade bitterhet inför framtiden.'
 else E'## Början\nKring 1750 började England bygga fabriker. Ångmaskinen gav kraft till maskiner som spann och vävde.\n\n## Nya städer\nMänniskor flyttade från landet till städerna för att jobba. Det kallas urbanisering.\n\n## Arbetet\nArbetsdagarna var långa och även barn jobbade. Det ledde till fackföreningar och nya lagar.\n\n## Följder\nVi fick järnvägar, billigare varor och ett nytt samhälle – men också föroreningar.'
end from d;